parameters.jsCode:
// Normalize comment payload from any platform
const body = $input.item.json.body || $input.item.json;

let normalized;

// Meta (Facebook/Instagram) comment format
if (body.object === 'page' || body.object === 'instagram') {
  const change = body.entry?.[0]?.changes?.[0];
  const value = change?.value || {};
  normalized = {
    source: 'meta',
    platform: body.object === 'instagram' ? 'instagram' : 'facebook',
    comment_id: value.comment_id || value.id,
    post_id: value.post_id || value.parent_id,
    sender_id: value.from?.id || 'unknown',
    sender_name: value.from?.name || 'Unknown',
    message: value.message || value.text || '',
    is_reply: !!value.parent_id,
    parent_comment_id: value.parent_id || null,
    timestamp: new Date().toISOString()
  };
} 
// TikTok comment format
else if (body.event === 'comment' || body.source === 'tiktok') {
  normalized = {
    source: 'tiktok',
    platform: 'tiktok',
    comment_id: body.comment_id || body.data?.comment_id,
    post_id: body.video_id || body.data?.video_id,
    sender_id: body.user_id || body.data?.user_id || 'unknown',
    sender_name: body.username || body.data?.username || 'Unknown',
    message: body.text || body.data?.text || '',
    is_reply: !!body.reply_to_comment_id,
    parent_comment_id: body.reply_to_comment_id || null,
    timestamp: new Date().toISOString()
  };
}
// Generic format
else {
  normalized = {
    source: body.source || 'unknown',
    platform: body.platform || 'unknown',
    comment_id: body.comment_id || 'unknown',
    post_id: body.post_id || 'unknown',
    sender_id: body.sender_id || 'unknown',
    sender_name: body.sender_name || 'Unknown',
    message: body.message || body.text || '',
    is_reply: false,
    parent_comment_id: null,
    timestamp: new Date().toISOString()
  };
}

return { json: normalized };

