parameters.jsCode:
const comment = $('Normalize Comment').item.json;
const aiResponse = $input.item.json.message.content;
let analysis;
try {
  analysis = JSON.parse(aiResponse);
} catch (e) {
  analysis = { requires_response: false, requires_moderation: false, sentiment: 'neutral' };
}

return {
  json: {
    ...comment,
    ...analysis,
    agent_id: 'community-manager',
    workflow_id: 'WF-COMMUNITY-COMMENTS'
  }
};

// Log moderation action - in production this would call the platform's moderation API
return {
  json: {
    action: 'moderate',
    moderation_action: $json.moderation_action,
    comment_id: $json.comment_id,
    platform: $json.platform,
    reason: $json.intent
  }
};
